for x in select value from jsonb_array_elements('[{"identity":"repo:https://github.com/marp-team/marp","slug":"marp-2561c6f9","name":"Marp","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Một file Markdown có thể trở thành slide, PDF và bộ ảnh để tái sử dụng nội dung.","description":"Marp là hệ sinh thái làm thuyết trình từ Markdown. Repo này là cửa vào các thành phần, không phải toàn bộ công cụ nằm trong một binary. Creator có thể viết một lần, dùng theme và xuất nhiều định dạng để chia sẻ bài học hoặc làm tài liệu đi kèm video.","long_description":"ĐIỂM NỔI BẬT\n• Marp Core/Marpit chuyển Markdown thành slide.\n• Marp CLI xuất HTML, PDF, PPTX và ảnh.\n• Có tích hợp VS Code để xem trước trong lúc viết.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nTạo slide hướng dẫn một workflow rồi xuất ảnh, kiểm tra từng trang trước khi tái biên tập thành carousel.\n\nBẮT ĐẦU\nChọn Marp CLI hoặc extension từ liên kết chính chủ, không tải app classic đã ngừng hoạt động.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nPhải kiểm tra font, ảnh và bố cục ở định dạng xuất. Không giả định PPTX xuất ra có mọi thành phần chỉnh sửa như deck làm trực tiếp bằng PowerPoint.","canonical_url":"https://github.com/marp-team/marp","repository_url":"https://github.com/marp-team/marp","documentation_url":"https://raw.githubusercontent.com/marp-team/marp/main/README.md","owner_name":"marp-team","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":81,"categories":["design","content"],"primaryCategory":"design","selectionReason":"Phù hợp Design & Frontend: Một file Markdown có thể trở thành slide, PDF và bộ ảnh để tái sử dụng nội dung. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Một file Markdown có thể trở thành slide, PDF và bộ ảnh để tái sử dụng nội dung.","highlights":["Marp Core/Marpit chuyển Markdown thành slide.","Marp CLI xuất HTML, PDF, PPTX và ảnh.","Có tích hợp VS Code để xem trước trong lúc viết."],"example":"Tạo slide hướng dẫn một workflow rồi xuất ảnh, kiểm tra từng trang trước khi tái biên tập thành carousel.","setup":"Chọn Marp CLI hoặc extension từ liên kết chính chủ, không tải app classic đã ngừng hoạt động.","limitations":"Phải kiểm tra font, ảnh và bố cục ở định dạng xuất. Không giả định PPTX xuất ra có mọi thành phần chỉnh sửa như deck làm trực tiếp bằng PowerPoint.","github":{"stars":12445,"forks":296,"observedAt":"2026-09-03T16:09:07.643Z","url":"https://github.com/marp-team/marp","pushedAt":"2026-07-29T19:35:44Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/marp-team/marp/main/README.md","observedAt":"2026-09-03T16:10:46.415Z","sha256":"ec27a30179e73ca21e9cd1848444f9b3077040187a2abc7a5e0d2a3e980d3273"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"marp-team/marp:metadata","source_url":"https://github.com/marp-team/marp","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Apresenton%2Fpresenton%20repo%3Amarp-team%2Fmarp%20repo%3Anextlevelbuilder%2Fui-ux-pro-max-skill%20repo%3Apbakaus%2Fimpeccable%20repo%3Aleonxlnx%2Ftaste-skill%20repo%3Ashadcn-ui%2Fui%20repo%3An8n-io%2Fn8n%20repo%3Aactivepieces%2Factivepieces&per_page=100","stars":12445,"forks":296,"license":"MIT"},"fetched_at":"2026-09-03T16:09:07.643Z"},{"source_type":"github","source_identifier":"marp-team/marp:readme:ec27a30179e73ca21e9cd1848444f9b3077040187a2abc7a5e0d2a3e980d3273","source_url":"https://raw.githubusercontent.com/marp-team/marp/main/README.md","raw_metadata":{"sha256":"ec27a30179e73ca21e9cd1848444f9b3077040187a2abc7a5e0d2a3e980d3273","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:46.415Z"}],"expected":null},{"identity":"repo:https://github.com/microsoft/markitdown","slug":"markitdown-3d33dc65","name":"MarkItDown","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Biến PDF, slide và tài liệu thành đầu vào dễ đọc cho AI trước khi viết.","description":"MarkItDown của Microsoft chuyển nhiều định dạng tệp sang Markdown, cố gắng giữ cấu trúc quan trọng như tiêu đề, danh sách, bảng và link. Đây là bước chuẩn bị tài liệu cho AI hoặc phân tích văn bản, không phải công cụ giữ nguyên thiết kế của PDF/PowerPoint. Nó hữu ích khi bạn muốn dùng tài liệu sản phẩm làm nguồn cho nội dung.","long_description":"ĐIỂM NỔI BẬT\n• Hỗ trợ nhiều loại tệp như PDF, Word, PowerPoint, Excel, HTML và EPUB.\n• Cài chọn các nhóm phụ thuộc phù hợp thay vì bật mọi định dạng.\n• Có CLI, giao diện Python và các tùy chọn OCR/transcription theo cấu hình.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nChuyển slide giới thiệu sản phẩm thành văn bản có cấu trúc rồi dùng để viết bài giải thích; đối chiếu lại bảng số liệu và nội dung trích dẫn với tệp gốc.\n\nBẮT ĐẦU\nCần Python theo yêu cầu README. Cài đúng nhóm định dạng cần dùng và chỉ xử lý tệp từ nguồn tin cậy trong môi trường có giới hạn quyền.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nKhông giữ nguyên bố cục để in/xuất bản. OCR và bảng có thể sai; chương trình có quyền truy cập tài nguyên của tiến trình chạy nó, nên không đưa đầu vào không tin cậy vào môi trường nhiều quyền.","canonical_url":"https://github.com/microsoft/markitdown","repository_url":"https://github.com/microsoft/markitdown","documentation_url":"https://raw.githubusercontent.com/microsoft/markitdown/main/README.md","owner_name":"microsoft","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":82,"categories":["research","content"],"primaryCategory":"research","selectionReason":"Phù hợp Research & Ý tưởng: Biến PDF, slide và tài liệu thành đầu vào dễ đọc cho AI trước khi viết. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Biến PDF, slide và tài liệu thành đầu vào dễ đọc cho AI trước khi viết.","highlights":["Hỗ trợ nhiều loại tệp như PDF, Word, PowerPoint, Excel, HTML và EPUB.","Cài chọn các nhóm phụ thuộc phù hợp thay vì bật mọi định dạng.","Có CLI, giao diện Python và các tùy chọn OCR/transcription theo cấu hình."],"example":"Chuyển slide giới thiệu sản phẩm thành văn bản có cấu trúc rồi dùng để viết bài giải thích; đối chiếu lại bảng số liệu và nội dung trích dẫn với tệp gốc.","setup":"Cần Python theo yêu cầu README. Cài đúng nhóm định dạng cần dùng và chỉ xử lý tệp từ nguồn tin cậy trong môi trường có giới hạn quyền.","limitations":"Không giữ nguyên bố cục để in/xuất bản. OCR và bảng có thể sai; chương trình có quyền truy cập tài nguyên của tiến trình chạy nó, nên không đưa đầu vào không tin cậy vào môi trường nhiều quyền.","github":{"stars":177952,"forks":13105,"observedAt":"2026-09-03T16:08:02.616Z","url":"https://github.com/microsoft/markitdown","pushedAt":"2026-09-03T15:40:25Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/microsoft/markitdown/main/README.md","observedAt":"2026-09-03T16:09:37.900Z","sha256":"1eee1ee277b03fb064bb08484d9a2decc9e84768baa5c5d82617f211eb162a12"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"microsoft/markitdown:metadata","source_url":"https://github.com/microsoft/markitdown","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Amendableai%2Ffirecrawl%20repo%3Aunclecode%2Fcrawl4ai%20repo%3Abrowser-use%2Fbrowser-use%20repo%3Ajina-ai%2Freader%20repo%3Amicrosoft%2Fmarkitdown%20repo%3Ahamidteimour%2Fseo-audit-skill%20repo%3AAgriciDaniel%2Fclaude-seo%20repo%3Aonur-genc%2Fseo-mcp&per_page=100","stars":177952,"forks":13105,"license":"MIT"},"fetched_at":"2026-09-03T16:08:02.616Z"},{"source_type":"github","source_identifier":"microsoft/markitdown:readme:1eee1ee277b03fb064bb08484d9a2decc9e84768baa5c5d82617f211eb162a12","source_url":"https://raw.githubusercontent.com/microsoft/markitdown/main/README.md","raw_metadata":{"sha256":"1eee1ee277b03fb064bb08484d9a2decc9e84768baa5c5d82617f211eb162a12","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:37.900Z"}],"expected":null},{"identity":"repo:https://github.com/firecrawl/firecrawl","slug":"firecrawl-eb561ab6","name":"Firecrawl","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Đưa nội dung web vào quy trình content dưới dạng có cấu trúc, thay vì copy từng trang.","description":"Firecrawl cung cấp API để tìm nguồn, đọc trang và trả về Markdown hoặc JSON cho ứng dụng AI. Các thao tác gồm search, scrape, crawl và map website; có dịch vụ được host và mã nguồn công khai. Với người làm nội dung, nó phù hợp làm khâu thu thập trong workflow đã có người hỗ trợ tích hợp.","long_description":"ĐIỂM NỔI BẬT\n• Tìm kiếm kèm nội dung trang và chuyển URL thành Markdown/JSON.\n• Có map, crawl và xử lý nhiều URL theo lô.\n• Tài liệu phân biệt các phần giấy phép; SDK và một số UI dùng MIT, phần chính dùng AGPL.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nThu thập thông tin từ website chính chủ của các công cụ vào bảng nghiên cứu, rồi để người biên tập kiểm nguồn và viết nhận xét riêng.\n\nBẮT ĐẦU\nThử playground/API chính chủ hoặc đọc hướng dẫn tự triển khai. Cấu hình giới hạn số trang, ngân sách và phạm vi nguồn trước khi chạy theo lô.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nAPI host có chi phí và bản tự host có thể không tương đương mọi tính năng dịch vụ. Không coi khả năng lấy được nội dung là quyền tái đăng; cần tuân thủ chính sách website và bảo vệ dữ liệu cá nhân.","canonical_url":"https://github.com/firecrawl/firecrawl","repository_url":"https://github.com/firecrawl/firecrawl","documentation_url":"https://raw.githubusercontent.com/firecrawl/firecrawl/main/README.md","owner_name":"firecrawl","license":"AGPL-3.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":83,"categories":["research","seo","automation"],"primaryCategory":"research","selectionReason":"Phù hợp Research & Ý tưởng: Đưa nội dung web vào quy trình content dưới dạng có cấu trúc, thay vì copy từng trang. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Đưa nội dung web vào quy trình content dưới dạng có cấu trúc, thay vì copy từng trang.","highlights":["Tìm kiếm kèm nội dung trang và chuyển URL thành Markdown/JSON.","Có map, crawl và xử lý nhiều URL theo lô.","Tài liệu phân biệt các phần giấy phép; SDK và một số UI dùng MIT, phần chính dùng AGPL."],"example":"Thu thập thông tin từ website chính chủ của các công cụ vào bảng nghiên cứu, rồi để người biên tập kiểm nguồn và viết nhận xét riêng.","setup":"Thử playground/API chính chủ hoặc đọc hướng dẫn tự triển khai. Cấu hình giới hạn số trang, ngân sách và phạm vi nguồn trước khi chạy theo lô.","limitations":"API host có chi phí và bản tự host có thể không tương đương mọi tính năng dịch vụ. Không coi khả năng lấy được nội dung là quyền tái đăng; cần tuân thủ chính sách website và bảo vệ dữ liệu cá nhân.","github":{"stars":176030,"forks":9636,"observedAt":"2026-09-03T16:12:06.580Z","url":"https://github.com/firecrawl/firecrawl","pushedAt":"2026-09-03T16:07:18Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/firecrawl/firecrawl/main/README.md","observedAt":"2026-09-03T16:12:59.992Z","sha256":"7eca70ba6eefd407c4c9e783f33ca68950460cc752af5c5940c601c82409049b"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"firecrawl/firecrawl:metadata","source_url":"https://github.com/firecrawl/firecrawl","raw_metadata":{"metadataUrl":"https://api.github.com/repositories/787076358","stars":176030,"forks":9636,"license":"AGPL-3.0"},"fetched_at":"2026-09-03T16:12:06.580Z"},{"source_type":"github","source_identifier":"firecrawl/firecrawl:readme:7eca70ba6eefd407c4c9e783f33ca68950460cc752af5c5940c601c82409049b","source_url":"https://raw.githubusercontent.com/firecrawl/firecrawl/main/README.md","raw_metadata":{"sha256":"7eca70ba6eefd407c4c9e783f33ca68950460cc752af5c5940c601c82409049b","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:12:59.992Z"}],"expected":"8ce5c2d6-60fd-4990-ab31-14b0129139ff"},{"identity":"repo:https://github.com/paddlepaddle/paddleocr","slug":"paddleocr-6b442a08","name":"PaddleOCR","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Biến tài liệu ảnh/PDF thành chữ và cấu trúc để bắt đầu nghiên cứu nội dung.","description":"PaddleOCR là bộ nhận dạng chữ và phân tích tài liệu. Với creator, công dụng gần gũi là lấy nội dung từ báo cáo, bảng và ảnh mà không nhập lại thủ công, rồi kiểm chứng trước khi viết bài. Đây là bước đọc tài liệu, không phải máy tự xác thực thông tin.","long_description":"ĐIỂM NỔI BẬT\n• Nhận dạng chữ đa ngôn ngữ với các model khác nhau.\n• Các pipeline tài liệu xuất Markdown/JSON, có xử lý cấu trúc bảng.\n• Có lựa chọn model nhỏ và backend theo phần cứng.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nTrích bảng từ báo cáo được phép sử dụng, đối chiếu số với trang gốc rồi viết một bài giải thích dễ hiểu.\n\nBẮT ĐẦU\nChọn OCR chữ thường hay pipeline tài liệu theo loại input; kiểm tra danh sách ngôn ngữ của model.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nOCR có thể sai dấu, số và thứ tự bảng. Không đăng số liệu quan trọng khi chưa so bản gốc; tài liệu riêng tư không nên gửi dịch vụ ngoài tùy tiện.","canonical_url":"https://github.com/PaddlePaddle/PaddleOCR","repository_url":"https://github.com/PaddlePaddle/PaddleOCR","documentation_url":"https://raw.githubusercontent.com/PaddlePaddle/PaddleOCR/main/README.md","owner_name":"PaddlePaddle","license":"Apache-2.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":84,"categories":["research","content","image"],"primaryCategory":"research","selectionReason":"Phù hợp Research & Ý tưởng: Biến tài liệu ảnh/PDF thành chữ và cấu trúc để bắt đầu nghiên cứu nội dung. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Biến tài liệu ảnh/PDF thành chữ và cấu trúc để bắt đầu nghiên cứu nội dung.","highlights":["Nhận dạng chữ đa ngôn ngữ với các model khác nhau.","Các pipeline tài liệu xuất Markdown/JSON, có xử lý cấu trúc bảng.","Có lựa chọn model nhỏ và backend theo phần cứng."],"example":"Trích bảng từ báo cáo được phép sử dụng, đối chiếu số với trang gốc rồi viết một bài giải thích dễ hiểu.","setup":"Chọn OCR chữ thường hay pipeline tài liệu theo loại input; kiểm tra danh sách ngôn ngữ của model.","limitations":"OCR có thể sai dấu, số và thứ tự bảng. Không đăng số liệu quan trọng khi chưa so bản gốc; tài liệu riêng tư không nên gửi dịch vụ ngoài tùy tiện.","github":{"stars":88795,"forks":11296,"observedAt":"2026-09-03T16:09:01.022Z","url":"https://github.com/PaddlePaddle/PaddleOCR","pushedAt":"2026-07-22T11:59:34Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/PaddlePaddle/PaddleOCR/main/README.md","observedAt":"2026-09-03T16:10:35.982Z","sha256":"3ebb5bcfcffafd2bf593f5252b4fc8de21abdb841c013048fc205b76a5c216ff"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"PaddlePaddle/PaddleOCR:metadata","source_url":"https://github.com/PaddlePaddle/PaddleOCR","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Avladmandic%2Fsdnext%20repo%3Alllyasviel%2Fstable-diffusion-webui-forge%20repo%3APaddlePaddle%2FPaddleOCR%20repo%3AUmi-OCR%2FUmi-OCR%20repo%3Apenpot%2Fpenpot%20repo%3Aexcalidraw%2Fexcalidraw%20repo%3Atldraw%2Ftldraw%20repo%3Aslidevjs%2Fslidev&per_page=100","stars":88795,"forks":11296,"license":"Apache-2.0"},"fetched_at":"2026-09-03T16:09:01.022Z"},{"source_type":"github","source_identifier":"PaddlePaddle/PaddleOCR:readme:3ebb5bcfcffafd2bf593f5252b4fc8de21abdb841c013048fc205b76a5c216ff","source_url":"https://raw.githubusercontent.com/PaddlePaddle/PaddleOCR/main/README.md","raw_metadata":{"sha256":"3ebb5bcfcffafd2bf593f5252b4fc8de21abdb841c013048fc205b76a5c216ff","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:35.982Z"}],"expected":null},{"identity":"repo:https://github.com/bytedance/deer-flow","slug":"deerflow-362c1d9b","name":"DeerFlow","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Một đề tài lớn có thể được chia thành nhiều nhánh nghiên cứu rồi gom lại thành đầu ra.","description":"DeerFlow 2.0 của ByteDance điều phối agent con, bộ nhớ, kỹ năng và môi trường thực thi tách biệt cho công việc nhiều bước. Với đội nội dung, hướng ứng dụng dễ hiểu là nghiên cứu một chủ đề, tổ chức phát hiện và chuẩn bị tài liệu đầu ra. Phiên bản 2 đã được viết lại; không nên lấy hướng dẫn bản 1 áp sang bản hiện tại.","long_description":"ĐIỂM NỔI BẬT\n• Chia nhiệm vụ cho agent con, kết hợp skills, công cụ và bộ nhớ.\n• Có trình hướng dẫn cấu hình mô hình, tìm kiếm web và quyền thực thi.\n• README ghi dự án đạt #1 GitHub Trending ngày 28/02/2026. Đây là tuyên bố lịch sử của tác giả, không phải xác nhận đang top 1 hôm nay.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nĐặt đề bài so sánh các cách làm phụ đề tiếng Việt, yêu cầu phân nhánh nghiên cứu và tổng hợp bảng ưu/nhược điểm kèm nguồn để bạn duyệt.\n\nBẮT ĐẦU\nTheo Quick Start của bản 2, ưu tiên cách triển khai được tác giả khuyến nghị; cấu hình mô hình và công cụ tìm kiếm trước khi chạy nghiên cứu.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nCần máy chủ/máy phát triển và khóa dịch vụ tương ứng. Agent có thể thao tác tệp hoặc chạy lệnh nếu được cấp quyền; bật sandbox, giới hạn quyền và kiểm chứng nguồn trong báo cáo.","canonical_url":"https://github.com/bytedance/deer-flow","repository_url":"https://github.com/bytedance/deer-flow","documentation_url":"https://raw.githubusercontent.com/bytedance/deer-flow/main/README.md","owner_name":"bytedance","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":85,"categories":["research","content","automation"],"primaryCategory":"research","selectionReason":"Phù hợp Research & Ý tưởng: Một đề tài lớn có thể được chia thành nhiều nhánh nghiên cứu rồi gom lại thành đầu ra. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Một đề tài lớn có thể được chia thành nhiều nhánh nghiên cứu rồi gom lại thành đầu ra.","highlights":["Chia nhiệm vụ cho agent con, kết hợp skills, công cụ và bộ nhớ.","Có trình hướng dẫn cấu hình mô hình, tìm kiếm web và quyền thực thi.","README ghi dự án đạt #1 GitHub Trending ngày 28/02/2026. Đây là tuyên bố lịch sử của tác giả, không phải xác nhận đang top 1 hôm nay."],"example":"Đặt đề bài so sánh các cách làm phụ đề tiếng Việt, yêu cầu phân nhánh nghiên cứu và tổng hợp bảng ưu/nhược điểm kèm nguồn để bạn duyệt.","setup":"Theo Quick Start của bản 2, ưu tiên cách triển khai được tác giả khuyến nghị; cấu hình mô hình và công cụ tìm kiếm trước khi chạy nghiên cứu.","limitations":"Cần máy chủ/máy phát triển và khóa dịch vụ tương ứng. Agent có thể thao tác tệp hoặc chạy lệnh nếu được cấp quyền; bật sandbox, giới hạn quyền và kiểm chứng nguồn trong báo cáo.","github":{"stars":81317,"forks":11210,"observedAt":"2026-09-03T16:07:56.087Z","url":"https://github.com/bytedance/deer-flow","pushedAt":"2026-09-03T16:03:49Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/bytedance/deer-flow/main/README.md","observedAt":"2026-09-03T16:09:31.851Z","sha256":"b3090565c9e954cf7970ba23b046ff105db6130d5a98be49475f977add392cb2"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"bytedance/deer-flow:metadata","source_url":"https://github.com/bytedance/deer-flow","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Adanny-avila%2FLibreChat%20repo%3Aassafelovic%2Fgpt-researcher%20repo%3Abytedance%2Fdeer-flow%20repo%3Aitzcrazykns%2Fvane%20repo%3Akhoj-ai%2Fkhoj%20repo%3Akarakeep-app%2Fkarakeep%20repo%3AFreshRSS%2FFreshRSS%20repo%3ADIYgod%2FRSSHub&per_page=100","stars":81317,"forks":11210,"license":"MIT"},"fetched_at":"2026-09-03T16:07:56.087Z"},{"source_type":"github","source_identifier":"bytedance/deer-flow:readme:b3090565c9e954cf7970ba23b046ff105db6130d5a98be49475f977add392cb2","source_url":"https://raw.githubusercontent.com/bytedance/deer-flow/main/README.md","raw_metadata":{"sha256":"b3090565c9e954cf7970ba23b046ff105db6130d5a98be49475f977add392cb2","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:31.851Z"}],"expected":"a20ae8ef-90d3-4311-928b-00e1db0a046f"},{"identity":"repo:https://github.com/unclecode/crawl4ai","slug":"crawl4ai-1100bab2","name":"Crawl4AI","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Đọc một website thành dữ liệu sạch trước khi giao AI làm bài tổng hợp.","description":"Crawl4AI chuyển nội dung web sang Markdown hoặc dữ liệu có cấu trúc phục vụ AI. Nó có công cụ dòng lệnh, thư viện Python và khả năng kiểm soát quá trình crawl. Công dụng với content/SEO là chuẩn bị tập nguồn có thể đọc và so sánh, thay vì chép thủ công từ nhiều trang; khâu triển khai vẫn cần người có kỹ thuật hỗ trợ.","long_description":"ĐIỂM NỔI BẬT\n• Xuất Markdown giữ các thành phần quan trọng như tiêu đề và bảng.\n• Có cache, quản lý phiên và giới hạn quá trình duyệt nhiều trang.\n• README nêu các bản vá bảo mật gần đây; phải kiểm tra phiên bản trước khi mở dịch vụ cho người khác.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nThu thập một tập trang tài liệu được phép truy cập, trích đặc tính sản phẩm rồi biên tập bài so sánh với link đối chiếu.\n\nBẮT ĐẦU\nLàm theo hướng dẫn cài và thiết lập trình duyệt; thử một URL trước, giới hạn số trang và quyền truy cập mạng.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nKhông phải ứng dụng kéo-thả dành cho người mới. Tôn trọng robots và điều khoản nguồn; không mở bản Docker cũ thiếu bảo vệ ra Internet. Crawl thành công không xác minh được nội dung nguồn là đúng.","canonical_url":"https://github.com/unclecode/crawl4ai","repository_url":"https://github.com/unclecode/crawl4ai","documentation_url":"https://raw.githubusercontent.com/unclecode/crawl4ai/main/README.md","owner_name":"unclecode","license":"Apache-2.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":86,"categories":["research","seo","automation"],"primaryCategory":"research","selectionReason":"Phù hợp Research & Ý tưởng: Đọc một website thành dữ liệu sạch trước khi giao AI làm bài tổng hợp. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Đọc một website thành dữ liệu sạch trước khi giao AI làm bài tổng hợp.","highlights":["Xuất Markdown giữ các thành phần quan trọng như tiêu đề và bảng.","Có cache, quản lý phiên và giới hạn quá trình duyệt nhiều trang.","README nêu các bản vá bảo mật gần đây; phải kiểm tra phiên bản trước khi mở dịch vụ cho người khác."],"example":"Thu thập một tập trang tài liệu được phép truy cập, trích đặc tính sản phẩm rồi biên tập bài so sánh với link đối chiếu.","setup":"Làm theo hướng dẫn cài và thiết lập trình duyệt; thử một URL trước, giới hạn số trang và quyền truy cập mạng.","limitations":"Không phải ứng dụng kéo-thả dành cho người mới. Tôn trọng robots và điều khoản nguồn; không mở bản Docker cũ thiếu bảo vệ ra Internet. Crawl thành công không xác minh được nội dung nguồn là đúng.","github":{"stars":81191,"forks":8374,"observedAt":"2026-09-03T16:08:02.616Z","url":"https://github.com/unclecode/crawl4ai","pushedAt":"2026-09-01T07:58:26Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/unclecode/crawl4ai/main/README.md","observedAt":"2026-09-03T16:09:39.369Z","sha256":"3de808095d5cb8101f2467b9646a795a76e1d81d8cf7d953c171c66d7ae0d3dd"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"unclecode/crawl4ai:metadata","source_url":"https://github.com/unclecode/crawl4ai","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Amendableai%2Ffirecrawl%20repo%3Aunclecode%2Fcrawl4ai%20repo%3Abrowser-use%2Fbrowser-use%20repo%3Ajina-ai%2Freader%20repo%3Amicrosoft%2Fmarkitdown%20repo%3Ahamidteimour%2Fseo-audit-skill%20repo%3AAgriciDaniel%2Fclaude-seo%20repo%3Aonur-genc%2Fseo-mcp&per_page=100","stars":81191,"forks":8374,"license":"Apache-2.0"},"fetched_at":"2026-09-03T16:08:02.616Z"},{"source_type":"github","source_identifier":"unclecode/crawl4ai:readme:3de808095d5cb8101f2467b9646a795a76e1d81d8cf7d953c171c66d7ae0d3dd","source_url":"https://raw.githubusercontent.com/unclecode/crawl4ai/main/README.md","raw_metadata":{"sha256":"3de808095d5cb8101f2467b9646a795a76e1d81d8cf7d953c171c66d7ae0d3dd","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:39.369Z"}],"expected":null},{"identity":"repo:https://github.com/diygod/rsshub","slug":"rsshub-8636ed82","name":"RSSHub","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Theo dõi nguồn của ngách mỗi ngày mà không cần nhớ mở từng trang.","description":"RSSHub cung cấp các route chuyển nội dung từ nhiều nguồn thành RSS, để bạn đọc tập trung trong ứng dụng feed. Nó phù hợp làm lớp thu thập đề tài cho newsletter, kênh tin hoặc người thường xuyên theo dõi cập nhật sản phẩm. RSSHub tạo dòng thông tin; quyết định chuyện nào đáng viết vẫn là công việc biên tập.","long_description":"ĐIỂM NỔI BẬT\n• Hệ sinh thái route cho nhiều nguồn nội dung, được cộng đồng bảo trì.\n• Có tài liệu tự triển khai và các dự án hỗ trợ phát hiện feed trên trình duyệt/điện thoại.\n• Có thể kết hợp với trình đọc RSS như Folo hoặc FreshRSS.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nTheo dõi vài nguồn chính chủ trong mảng video AI, gom bài mới vào một feed rồi chọn tin có bằng chứng để viết bản tin tuần.\n\nBẮT ĐẦU\nTìm route phù hợp trong tài liệu chính chủ và thêm vào trình đọc RSS; nếu cần tự host, làm theo hướng dẫn deployment.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nRoute có thể hỏng khi website đổi cấu trúc hoặc chính sách. Không mặc định được phép thu thập mọi nguồn; giữ liên kết gốc, tôn trọng bản quyền và giới hạn truy cập.","canonical_url":"https://github.com/DIYgod/RSSHub","repository_url":"https://github.com/DIYgod/RSSHub","documentation_url":"https://raw.githubusercontent.com/DIYgod/RSSHub/master/README.md","owner_name":"DIYgod","license":"AGPL-3.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":87,"categories":["research","content","social"],"primaryCategory":"research","selectionReason":"Phù hợp Research & Ý tưởng: Theo dõi nguồn của ngách mỗi ngày mà không cần nhớ mở từng trang. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Theo dõi nguồn của ngách mỗi ngày mà không cần nhớ mở từng trang.","highlights":["Hệ sinh thái route cho nhiều nguồn nội dung, được cộng đồng bảo trì.","Có tài liệu tự triển khai và các dự án hỗ trợ phát hiện feed trên trình duyệt/điện thoại.","Có thể kết hợp với trình đọc RSS như Folo hoặc FreshRSS."],"example":"Theo dõi vài nguồn chính chủ trong mảng video AI, gom bài mới vào một feed rồi chọn tin có bằng chứng để viết bản tin tuần.","setup":"Tìm route phù hợp trong tài liệu chính chủ và thêm vào trình đọc RSS; nếu cần tự host, làm theo hướng dẫn deployment.","limitations":"Route có thể hỏng khi website đổi cấu trúc hoặc chính sách. Không mặc định được phép thu thập mọi nguồn; giữ liên kết gốc, tôn trọng bản quyền và giới hạn truy cập.","github":{"stars":46004,"forks":10182,"observedAt":"2026-09-03T16:07:56.087Z","url":"https://github.com/DIYgod/RSSHub","pushedAt":"2026-09-03T12:55:31Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/DIYgod/RSSHub/master/README.md","observedAt":"2026-09-03T16:09:32.787Z","sha256":"80870efeb346786058ca9ede5a32b16c0c700b1e5664e24fbb84fc24aa9c4dba"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"DIYgod/RSSHub:metadata","source_url":"https://github.com/DIYgod/RSSHub","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Adanny-avila%2FLibreChat%20repo%3Aassafelovic%2Fgpt-researcher%20repo%3Abytedance%2Fdeer-flow%20repo%3Aitzcrazykns%2Fvane%20repo%3Akhoj-ai%2Fkhoj%20repo%3Akarakeep-app%2Fkarakeep%20repo%3AFreshRSS%2FFreshRSS%20repo%3ADIYgod%2FRSSHub&per_page=100","stars":46004,"forks":10182,"license":"AGPL-3.0"},"fetched_at":"2026-09-03T16:07:56.087Z"},{"source_type":"github","source_identifier":"DIYgod/RSSHub:readme:80870efeb346786058ca9ede5a32b16c0c700b1e5664e24fbb84fc24aa9c4dba","source_url":"https://raw.githubusercontent.com/DIYgod/RSSHub/master/README.md","raw_metadata":{"sha256":"80870efeb346786058ca9ede5a32b16c0c700b1e5664e24fbb84fc24aa9c4dba","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:32.787Z"}],"expected":null},{"identity":"repo:https://github.com/khoj-ai/khoj","slug":"khoj-2a1dd821","name":"Khoj","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Hỏi lại kho ghi chú của mình, thay vì tìm bằng trí nhớ xem đã lưu ở đâu.","description":"Khoj là trợ lý AI cá nhân có thể trả lời từ tài liệu của bạn và nguồn web. Nó hỗ trợ nhiều loại tệp, mô hình cục bộ hoặc online và các điểm truy cập như trình duyệt, desktop hay Obsidian. Creator có thể dùng nó làm lớp tra cứu trên kho research và định hướng thương hiệu đã tích lũy.","long_description":"ĐIỂM NỔI BẬT\n• Tìm và hỏi trên PDF, Markdown, Word, Notion cùng nhiều dạng tài liệu.\n• Tạo agent với tri thức và vai trò riêng; có tìm kiếm theo ngữ nghĩa.\n• Có nhánh tự động hóa nghiên cứu, bản tin và thông báo theo cấu hình.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nNạp các ghi chú nghiên cứu của kênh, hỏi những luận điểm đã có nguồn rồi dùng kết quả làm dàn ý cho tập tiếp theo.\n\nBẮT ĐẦU\nThử ứng dụng cloud chính chủ hoặc xem hướng dẫn self-host; chọn mô hình và loại tài liệu muốn kết nối.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nCâu trả lời từ tài liệu vẫn có thể suy diễn sai. Dùng mô hình online có thể gửi ngữ cảnh ra nhà cung cấp; tự host không tự động đồng nghĩa toàn bộ xử lý đều offline.","canonical_url":"https://github.com/khoj-ai/khoj","repository_url":"https://github.com/khoj-ai/khoj","documentation_url":"https://raw.githubusercontent.com/khoj-ai/khoj/master/README.md","owner_name":"khoj-ai","license":"AGPL-3.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":88,"categories":["research","content"],"primaryCategory":"research","selectionReason":"Phù hợp Research & Ý tưởng: Hỏi lại kho ghi chú của mình, thay vì tìm bằng trí nhớ xem đã lưu ở đâu. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Hỏi lại kho ghi chú của mình, thay vì tìm bằng trí nhớ xem đã lưu ở đâu.","highlights":["Tìm và hỏi trên PDF, Markdown, Word, Notion cùng nhiều dạng tài liệu.","Tạo agent với tri thức và vai trò riêng; có tìm kiếm theo ngữ nghĩa.","Có nhánh tự động hóa nghiên cứu, bản tin và thông báo theo cấu hình."],"example":"Nạp các ghi chú nghiên cứu của kênh, hỏi những luận điểm đã có nguồn rồi dùng kết quả làm dàn ý cho tập tiếp theo.","setup":"Thử ứng dụng cloud chính chủ hoặc xem hướng dẫn self-host; chọn mô hình và loại tài liệu muốn kết nối.","limitations":"Câu trả lời từ tài liệu vẫn có thể suy diễn sai. Dùng mô hình online có thể gửi ngữ cảnh ra nhà cung cấp; tự host không tự động đồng nghĩa toàn bộ xử lý đều offline.","github":{"stars":37041,"forks":2451,"observedAt":"2026-09-03T16:07:56.087Z","url":"https://github.com/khoj-ai/khoj","pushedAt":"2026-08-02T01:55:40Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/khoj-ai/khoj/master/README.md","observedAt":"2026-09-03T16:09:34.119Z","sha256":"f43b29f1ad9d5792d4a2b1d46454c26249212c5f93e59923adc718463a3ac1ba"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"khoj-ai/khoj:metadata","source_url":"https://github.com/khoj-ai/khoj","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Adanny-avila%2FLibreChat%20repo%3Aassafelovic%2Fgpt-researcher%20repo%3Abytedance%2Fdeer-flow%20repo%3Aitzcrazykns%2Fvane%20repo%3Akhoj-ai%2Fkhoj%20repo%3Akarakeep-app%2Fkarakeep%20repo%3AFreshRSS%2FFreshRSS%20repo%3ADIYgod%2FRSSHub&per_page=100","stars":37041,"forks":2451,"license":"AGPL-3.0"},"fetched_at":"2026-09-03T16:07:56.087Z"},{"source_type":"github","source_identifier":"khoj-ai/khoj:readme:f43b29f1ad9d5792d4a2b1d46454c26249212c5f93e59923adc718463a3ac1ba","source_url":"https://raw.githubusercontent.com/khoj-ai/khoj/master/README.md","raw_metadata":{"sha256":"f43b29f1ad9d5792d4a2b1d46454c26249212c5f93e59923adc718463a3ac1ba","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:34.119Z"}],"expected":null},{"identity":"repo:https://github.com/itzcrazykns/vane","slug":"vane-3dfa6a3a","name":"Vane","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Tìm câu trả lời có đường quay về nguồn, không chỉ một đoạn văn nghe hợp lý.","description":"Vane là công cụ trả lời bằng AI có thể tự triển khai, kết hợp tìm kiếm web với mô hình local hoặc nhà cung cấp cloud. Giao diện cho phép chọn mức độ tìm kiếm, phạm vi nguồn và hỏi trên tệp tải lên. Nó hữu ích ở bước tìm hiểu chủ đề và gom đường dẫn trước khi viết bài hay kịch bản.","long_description":"ĐIỂM NỔI BẬT\n• Các chế độ tìm nhanh, cân bằng và nghiên cứu sâu hơn.\n• Tìm web, thảo luận, bài học thuật; hỗ trợ giới hạn theo tên miền.\n• Có tìm hình/video và tải tài liệu để hỏi, với nguồn trích dẫn trong câu trả lời.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nTìm thông tin chính chủ về một tool và giới hạn tên miền nguồn, sau đó mở từng dẫn chứng trước khi viết bài giới thiệu.\n\nBẮT ĐẦU\nREADME khuyến nghị Docker có SearxNG đi kèm. Mở giao diện thiết lập và cấu hình mô hình local hoặc API bạn dùng.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nTrích dẫn không bảo đảm câu trả lời diễn giải đúng. Kết nối mô hình cloud vẫn đưa dữ liệu tới dịch vụ đó; kết quả hình/video không cấp quyền tái đăng.","canonical_url":"https://github.com/ItzCrazyKns/Vane","repository_url":"https://github.com/ItzCrazyKns/Vane","documentation_url":"https://raw.githubusercontent.com/ItzCrazyKns/Vane/master/README.md","owner_name":"ItzCrazyKns","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":89,"categories":["research","content"],"primaryCategory":"research","selectionReason":"Phù hợp Research & Ý tưởng: Tìm câu trả lời có đường quay về nguồn, không chỉ một đoạn văn nghe hợp lý. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Tìm câu trả lời có đường quay về nguồn, không chỉ một đoạn văn nghe hợp lý.","highlights":["Các chế độ tìm nhanh, cân bằng và nghiên cứu sâu hơn.","Tìm web, thảo luận, bài học thuật; hỗ trợ giới hạn theo tên miền.","Có tìm hình/video và tải tài liệu để hỏi, với nguồn trích dẫn trong câu trả lời."],"example":"Tìm thông tin chính chủ về một tool và giới hạn tên miền nguồn, sau đó mở từng dẫn chứng trước khi viết bài giới thiệu.","setup":"README khuyến nghị Docker có SearxNG đi kèm. Mở giao diện thiết lập và cấu hình mô hình local hoặc API bạn dùng.","limitations":"Trích dẫn không bảo đảm câu trả lời diễn giải đúng. Kết nối mô hình cloud vẫn đưa dữ liệu tới dịch vụ đó; kết quả hình/video không cấp quyền tái đăng.","github":{"stars":36597,"forks":4068,"observedAt":"2026-09-03T16:07:56.087Z","url":"https://github.com/ItzCrazyKns/Vane","pushedAt":"2026-09-01T14:12:12Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/ItzCrazyKns/Vane/master/README.md","observedAt":"2026-09-03T16:09:34.987Z","sha256":"5d534fafeb1e3d1355751e82241b74ab6c5e3d89561e98178512a704dba28268"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"ItzCrazyKns/Vane:metadata","source_url":"https://github.com/ItzCrazyKns/Vane","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Adanny-avila%2FLibreChat%20repo%3Aassafelovic%2Fgpt-researcher%20repo%3Abytedance%2Fdeer-flow%20repo%3Aitzcrazykns%2Fvane%20repo%3Akhoj-ai%2Fkhoj%20repo%3Akarakeep-app%2Fkarakeep%20repo%3AFreshRSS%2FFreshRSS%20repo%3ADIYgod%2FRSSHub&per_page=100","stars":36597,"forks":4068,"license":"MIT"},"fetched_at":"2026-09-03T16:07:56.087Z"},{"source_type":"github","source_identifier":"ItzCrazyKns/Vane:readme:5d534fafeb1e3d1355751e82241b74ab6c5e3d89561e98178512a704dba28268","source_url":"https://raw.githubusercontent.com/ItzCrazyKns/Vane/master/README.md","raw_metadata":{"sha256":"5d534fafeb1e3d1355751e82241b74ab6c5e3d89561e98178512a704dba28268","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:34.987Z"}],"expected":"cadea29c-d41e-4857-820f-22c5db9b1119"},{"identity":"repo:https://github.com/assafelovic/gpt-researcher","slug":"gpt-researcher-0cec2e49","name":"GPT Researcher","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Cho AI lập câu hỏi nghiên cứu trước khi viết báo cáo có dẫn nguồn.","description":"GPT Researcher xây báo cáo từ web và tài liệu cục bộ bằng các bước lập kế hoạch, thu thập, tóm tắt nguồn và tổng hợp. Với creator làm bài phân tích hoặc video giải thích, nó có thể chuẩn bị hồ sơ nghiên cứu để người viết chọn góc kể chuyện. Không nên coi báo cáo tự động là nội dung đã qua fact-check.","long_description":"ĐIỂM NỔI BẬT\n• Phân rã đề bài thành câu hỏi nghiên cứu rồi theo dõi nguồn cho từng phần.\n• Kết hợp tài liệu local và web, có tùy biến theo lĩnh vực.\n• Có giao diện, gói Python, cách cài dạng skill và các định dạng xuất báo cáo như PDF/Word.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nNghiên cứu ba giải pháp chuyển giọng nói thành phụ đề, yêu cầu so sánh yêu cầu máy, giấy phép và cách dùng rồi tự kiểm tra các nhận định quan trọng.\n\nBẮT ĐẦU\nLàm theo Getting Started, chuẩn bị Python và API mô hình/tìm kiếm hoặc cấu hình thay thế được hỗ trợ. Bắt đầu bằng đề bài ngắn.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nNghiên cứu nhiều nguồn có thể tốn tiền API và thời gian. Số nguồn hay độ dài báo cáo không thay thế chất lượng nguồn; không dùng nguyên xi cho chủ đề cần chuyên gia kiểm duyệt.","canonical_url":"https://github.com/assafelovic/gpt-researcher","repository_url":"https://github.com/assafelovic/gpt-researcher","documentation_url":"https://raw.githubusercontent.com/assafelovic/gpt-researcher/main/README.md","owner_name":"assafelovic","license":"Apache-2.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":90,"categories":["research","content"],"primaryCategory":"research","selectionReason":"Phù hợp Research & Ý tưởng: Cho AI lập câu hỏi nghiên cứu trước khi viết báo cáo có dẫn nguồn. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Cho AI lập câu hỏi nghiên cứu trước khi viết báo cáo có dẫn nguồn.","highlights":["Phân rã đề bài thành câu hỏi nghiên cứu rồi theo dõi nguồn cho từng phần.","Kết hợp tài liệu local và web, có tùy biến theo lĩnh vực.","Có giao diện, gói Python, cách cài dạng skill và các định dạng xuất báo cáo như PDF/Word."],"example":"Nghiên cứu ba giải pháp chuyển giọng nói thành phụ đề, yêu cầu so sánh yêu cầu máy, giấy phép và cách dùng rồi tự kiểm tra các nhận định quan trọng.","setup":"Làm theo Getting Started, chuẩn bị Python và API mô hình/tìm kiếm hoặc cấu hình thay thế được hỗ trợ. Bắt đầu bằng đề bài ngắn.","limitations":"Nghiên cứu nhiều nguồn có thể tốn tiền API và thời gian. Số nguồn hay độ dài báo cáo không thay thế chất lượng nguồn; không dùng nguyên xi cho chủ đề cần chuyên gia kiểm duyệt.","github":{"stars":29273,"forks":3974,"observedAt":"2026-09-03T16:07:56.087Z","url":"https://github.com/assafelovic/gpt-researcher","pushedAt":"2026-08-27T19:34:56Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/assafelovic/gpt-researcher/main/README.md","observedAt":"2026-09-03T16:09:35.555Z","sha256":"d79bbcd7196317af10b6cc84baf30bb84ad0fc67d16dd61552fc139461548507"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"assafelovic/gpt-researcher:metadata","source_url":"https://github.com/assafelovic/gpt-researcher","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Adanny-avila%2FLibreChat%20repo%3Aassafelovic%2Fgpt-researcher%20repo%3Abytedance%2Fdeer-flow%20repo%3Aitzcrazykns%2Fvane%20repo%3Akhoj-ai%2Fkhoj%20repo%3Akarakeep-app%2Fkarakeep%20repo%3AFreshRSS%2FFreshRSS%20repo%3ADIYgod%2FRSSHub&per_page=100","stars":29273,"forks":3974,"license":"Apache-2.0"},"fetched_at":"2026-09-03T16:07:56.087Z"},{"source_type":"github","source_identifier":"assafelovic/gpt-researcher:readme:d79bbcd7196317af10b6cc84baf30bb84ad0fc67d16dd61552fc139461548507","source_url":"https://raw.githubusercontent.com/assafelovic/gpt-researcher/main/README.md","raw_metadata":{"sha256":"d79bbcd7196317af10b6cc84baf30bb84ad0fc67d16dd61552fc139461548507","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:09:35.555Z"}],"expected":null}]'::jsonb) loop
  select * into existing from public.resources where external_identity=x->>'identity' for update;
  already:=found and existing.import_metadata->>'creatorImportHash'='70246f4c4a2f7774b985a83b1046397afb219b4521ac7e2ac8ae08790ad028cf';
  if already then continue; end if;
  if existing.id is not null and (existing.id::text is distinct from x->>'expected' or existing.editorial_revision<>0 or existing.status<>'CANDIDATE') then raise exception 'Candidate changed since snapshot: %',x->>'identity'; end if;
  if existing.id is null and x->>'expected' is not null then raise exception 'Candidate disappeared since snapshot'; end if;
  if existing.id is null then
    insert into public.resources(external_identity,slug,type,name,canonical_url) values(x->>'identity',x->>'slug',(x->>'type')::public.resource_type,x->>'name',x->>'canonical_url') returning id into rid;
  else rid:=existing.id; end if;
  update public.resources set name=x->>'name',type=(x->>'type')::public.resource_type,tagline=x->>'tagline',description=x->>'description',long_description=x->>'long_description',canonical_url=x->>'canonical_url',repository_url=x->>'repository_url',documentation_url=x->>'documentation_url',owner_name=x->>'owner_name',license=x->>'license',import_metadata=import_metadata||(x->'import_metadata')||jsonb_build_object('creatorImportHash','70246f4c4a2f7774b985a83b1046397afb219b4521ac7e2ac8ae08790ad028cf'),last_source_update_at=(x#>>'{import_metadata,creatorCatalog,github,observedAt}')::timestamptz,editorial_revision=editorial_revision+1,updated_at=now() where id=rid;
  for s in select value from jsonb_array_elements(x->'sources') loop
    insert into public.resource_sources(resource_id,source_type,source_identifier,source_url,raw_metadata,fetched_at) values(rid,s->>'source_type',s->>'source_identifier',s->>'source_url',s->'raw_metadata',(s->>'fetched_at')::timestamptz) on conflict(resource_id,source_type,source_identifier) do update set source_url=excluded.source_url,raw_metadata=excluded.raw_metadata,fetched_at=excluded.fetched_at;
  end loop;
  insert into public.resource_metric_snapshots(resource_id,source_type,metric_key,metric_value,captured_at) values(rid,'github','stars',(x#>>'{import_metadata,creatorCatalog,github,stars}')::numeric,(x#>>'{import_metadata,creatorCatalog,github,observedAt}')::timestamptz),(rid,'github','forks',(x#>>'{import_metadata,creatorCatalog,github,forks}')::numeric,(x#>>'{import_metadata,creatorCatalog,github,observedAt}')::timestamptz) on conflict do nothing;
  insert into public.resource_evidence_jobs(resource_id) values(rid) on conflict do nothing;
end loop;
end $creator_import$;
commit;
select count(*)::int as dossiers_written from public.resources where import_metadata->>'creatorImportHash'='70246f4c4a2f7774b985a83b1046397afb219b4521ac7e2ac8ae08790ad028cf';